#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
root=$(cd -- "$(dirname -- "$(readlink -f -- "$0")")/.." && pwd)
cd "$root"
[[ -f .env && -f .env.postgres && -f compose.override.yaml ]] || { echo 'Configuration PostgreSQL du serveur absente.' >&2; exit 1; }
[[ $(stat -c '%u' .env.postgres) == 0 && $(stat -c '%a' .env.postgres) == 600 ]] || { echo 'La configuration privée PostgreSQL doit appartenir à root et être en mode 600.' >&2; exit 1; }
# This file is generated by the migration installer and readable only by root.
source .env.postgres
[[ ${TEKNIKA_DATABASE:-} =~ ^[a-z][a-z0-9_]{0,62}$ ]] || { echo 'Nom de base PostgreSQL invalide.' >&2; exit 1; }
[[ ${COMPOSE_PROJECT_NAME:-} =~ ^[a-z0-9][a-z0-9_-]*$ ]] || { echo 'Nom du projet Docker invalide.' >&2; exit 1; }
compose=(docker compose --project-directory "$root" --project-name "$COMPOSE_PROJECT_NAME" --env-file .env --env-file .env.postgres -f compose.yaml -f compose.override.yaml)
destination=/var/backups/timeteknika
install -d -m 700 "$destination"
partial=$(mktemp "$destination/.postgres.XXXXXXXX.dump")
trap 'rm -f -- "$partial"' EXIT
"${compose[@]}" exec -T postgres pg_dump -U postgres -d "$TEKNIKA_DATABASE" --format=custom --no-owner --no-acl > "$partial"
[[ -s "$partial" ]] || { echo 'Sauvegarde PostgreSQL vide.' >&2; exit 1; }
"${compose[@]}" exec -T postgres pg_restore --list < "$partial" > /dev/null
name="timeteknika-postgres-$(date -u +%Y%m%dT%H%M%S%NZ).dump"
mv -- "$partial" "$destination/$name"
sha256sum "$destination/$name" > "$destination/$name.sha256"
chmod 600 "$destination/$name" "$destination/$name.sha256"
trap - EXIT
echo "Sauvegarde PostgreSQL : $destination/$name"
